using System.IO;
using System.Windows;
namespace MRS;
internal static class Update048Tests
{
 internal static void Run(Action<bool,string> check)
 {
  string root=Path.Combine(AppContext.BaseDirectory,"tests-048",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var now=DateTimeOffset.UtcNow;
  var site=new SiteChannelData("P25",["P25","ABCDE-123","RFSS 1 - Site 2"],"P25:ABCDE-123:1:2",851025000,"00-0002","Voice channel","WACN ABCDE; System 123; RFSS 1; Site 2; NAC 293",Seen:now);
  var db=new FrequencyLibrary(Path.Combine(root,"rename.json"));db.SaveSiteChannels([site]);var system=db.Items.Single(c=>c.IsFolder&&c.Name=="ABCDE-123");var folder=db.Items.Single(c=>c.IsFolder&&c.Name=="RFSS 1 - Site 2");db.Upsert(system with{Name="ABCDE-123 Test utility"});db.Upsert(folder with{Name="Site 2 Main tower"});int count=db.Items.Count;db.SaveSiteChannels([site with{Hz=851050000}]);
  check(db.Items.Count(c=>c.IsFolder)==3&&db.Items.Count==count+1,"Renamed system/site folders receive new channels without duplicate folders");check(db.Items.Where(c=>!c.IsFolder).All(c=>c.ParentId==folder.Id),"New discoveries follow the identity-bound renamed site");check(new FrequencyLibrary(Path.Combine(root,"rename.json")).Items.Single(c=>c.Id==system.Id).Name.Contains("Test utility"),"Renamed folder binding survives restart");
  var legacy=new FrequencyLibrary(Path.Combine(root,"legacy-rename.json"));var rootFolder=new FrequencyItem{Name="P25",IsFolder=true};var legacySystem=new FrequencyItem{Name="Test utility",IsFolder=true,ParentId=rootFolder.Id};var legacySite=new FrequencyItem{Name="My tower",IsFolder=true,ParentId=legacySystem.Id};legacy.Upsert(rootFolder);legacy.Upsert(legacySystem);legacy.Upsert(legacySite);legacy.Upsert(site.Draft() with{ParentId=legacySite.Id});legacy.SaveSiteChannels([site with{Hz=851075000}]);check(legacy.Items.Count(c=>c.IsFolder)==3&&legacy.Items.Where(c=>!c.IsFolder).All(c=>c.ParentId==legacySite.Id),"Legacy renamed folders adopt identity bindings from descendant evidence");
  check(db.PreviewCleanup(true,true,false,0,0).Channels.Where(c=>!c.IsFolder).All(c=>c.ParentId==folder.Id),"Cleanup organization also respects renamed identity-bound folders");
  var dmr=new SiteChannelData("DMR",["DMR","Unidentified system","Network 5","Site 1"],"DMR:Unidentified system:Network 5:Site 1",452300000,"","Observed carrier","Network 5; Site 1; CC 6",Seen:now);
  var signals=new FrequencyLibrary(Path.Combine(root,"dedup.json"));signals.SaveSiteChannels([dmr]);var saved=signals.Items.Single(c=>!c.IsFolder);signals.Upsert(saved with{Name="My carrier",Notes="Keep notes"});signals.SaveSiteChannels([dmr with{Hz=452300500,Seen=now.AddSeconds(1)}]);var same=signals.Items.Single(c=>!c.IsFolder);check(same.Id==saved.Id&&same.FrequencyHz==452300000&&same.LastObservedFrequencyHz==452300500,"Small tuning offsets enrich one saved channel without changing its exact center");check(same.Name=="My carrier"&&same.Notes=="Keep notes","Discovery updates preserve custom labels and notes");
  var cap=dmr with{Folders=["DMR","Capacity Plus","Network 5","Site 1"],Scope="DMR:Capacity Plus:Network 5:Site 1",Identifiers="Capacity Plus; Network 5; Site 1; CC 6"};signals.SaveSiteChannels([cap]);check(signals.Items.Single(c=>!c.IsFolder).Id==saved.Id&&signals.Items.Single(c=>!c.IsFolder).SiteScope==cap.Scope,"Generic DMR can gain Cap+ classification without another entry");signals.SaveSiteChannels([dmr]);check(signals.Items.Single(c=>!c.IsFolder).SiteScope==cap.Scope,"Later generic observations do not downgrade a known system subtype");
  var offsets=new FrequencyLibrary(Path.Combine(root,"larger-offsets.json"));offsets.SaveSiteChannels([dmr]);offsets.SaveSiteChannels([dmr with{Hz=dmr.Hz+3000}]);check(offsets.Items.Count(c=>!c.IsFolder)==1&&offsets.PendingDiscoveries.Count==1,"Larger nearby tuning offsets are held rather than saved as another carrier");offsets.ResolveDiscovery(offsets.PendingDiscoveries[0].Key,offsets.Items.Single(c=>!c.IsFolder).Id,false);check(offsets.Items.Single(c=>!c.IsFolder).FrequencyHz==dmr.Hz&&offsets.PendingDiscoveries.Count==0,"Explicit compatible offset review retains the saved channel center");
  var unknown=dmr with{Scope="DMR:Unidentified system:Unassigned at 452.300000:Unresolved site",Folders=["DMR","Unidentified system","Unassigned at 452.300000","Unresolved site"],Identifiers="DMR; CC 6",Evidence="Provisional identity"};signals.SaveSiteChannels([unknown]);check(signals.Items.Count(c=>!c.IsFolder)==1&&signals.Items.Single(c=>!c.IsFolder).Signaling.Contains("Site 1"),"Partial observations retain previously learned site identity");
  var provisional=new FrequencyLibrary(Path.Combine(root,"partial-offsets.json"));provisional.SaveSiteChannels([unknown]);int folderCount=provisional.Items.Count(c=>c.IsFolder);provisional.SaveSiteChannels([unknown with{Hz=unknown.Hz+500,Scope=unknown.Scope.Replace("452.300000","452.300500"),Folders=["DMR","Unidentified system","Unassigned at 452.300500","Unresolved site"]}]);check(provisional.Items.Count(c=>!c.IsFolder)==1&&provisional.Items.Count(c=>c.IsFolder)==folderCount,"Offset-only changes to a provisional identity do not create new folder branches");
  signals.SaveSiteChannels([cap with{Identifiers="Network 5; Site 1; CC 7"}]);check(signals.Items.Count(c=>!c.IsFolder)==1&&signals.PendingDiscoveries.Count==1,"Conflicting identity is held for review without a duplicate marker");
  signals.SetDiscoveryPolicy(true);signals.SaveSiteChannels([cap with{Hz=453000000}]);check(signals.Items.Count(c=>!c.IsFolder)==1&&signals.PendingDiscoveries.Count==2,"Research mode holds genuinely new channels");signals=new FrequencyLibrary(Path.Combine(root,"dedup.json"));check(signals.UpdateExistingOnly&&signals.PendingDiscoveries.Count==2,"Research policy and held discoveries survive restart");var pending=signals.PendingDiscoveries.Single(p=>p.Data.Hz==453000000);signals.ResolveDiscovery(pending.Key,null,true);check(signals.Items.Count(c=>!c.IsFolder)==2,"Explicit review can retain a channel as a separate entry");
  var held=new FrequencyLibrary(Path.Combine(root,"coalesced-held.json"));held.SetDiscoveryPolicy(true);held.SaveSiteChannels([cap with{Hz=454000000}]);held.SaveSiteChannels([cap with{Hz=454000500}]);check(held.PendingDiscoveries.Count==1,"Nearby compatible research observations coalesce in the review queue");held.ResolveDiscovery(held.PendingDiscoveries[0].Key,null,true);check(held.PendingDiscoveries.Count==0&&held.Items.Count(c=>!c.IsFolder)==1,"Review approval removes the coalesced held observation");
  var manual=new FrequencyLibrary(Path.Combine(root,"manual.json"));var custom=new FrequencyItem{Name="Hand-entered channel",FrequencyHz=452300000,Protocols="DMR"};manual.Upsert(custom);manual.SaveSiteChannels([dmr]);manual.SaveSiteChannels([dmr]);check(manual.Items.Count(c=>!c.IsFolder)==1&&manual.Items.Single(c=>!c.IsFolder).ParentId==null,"Unique unscoped manual channels are enriched without moving custom placement");
  var ambiguous=new FrequencyLibrary(Path.Combine(root,"ambiguous.json"));ambiguous.Upsert(custom);ambiguous.Upsert(custom with{Id=Guid.NewGuid(),Name="Another saved candidate"});ambiguous.SaveSiteChannels([dmr]);check(ambiguous.Items.Count(c=>!c.IsFolder)==2&&ambiguous.PendingDiscoveries.Count==1,"Several possible matches are held rather than generating a third saved entry");
  var view=new SpectrumView{Width=1000,Height=600};view.Measure(new Size(1000,600));view.Arrange(new Rect(0,0,1000,600));view.SetRf(452300000,240000);view.SetChannel(new(452300000,"NFM",12500));view.Configure(view.Settings with{ViewMode=1,Zoom=64});view.PanView(.9);check(view.Settings.ViewMode==1&&Math.Abs(view.VisibleCenter-452300000)<1,"Explicit pan cannot release center lock");view.BeginDrag(new(300,250));view.ContinueDrag(new(500,250));view.EndDrag(new(500,250));check(view.Settings.ViewMode==1,"Dragging preserves center-lock mode");view.Configure(view.Settings with{Zoom=128});view.SetChannel(new(452301000,"NFM",12500));check(Math.Abs(view.VisibleCenter-452301000)<1,"Locked zoom and subsequent tune remain centered");view.ResetView();check(view.Settings.ViewMode==1,"Full span does not disable center lock");view.Configure(view.Settings with{ViewMode=2});view.PanView(.2);check(view.Settings.ViewMode==2,"User can deliberately choose free view and pan");
  check(new DisplaySettings().SnapMode==3,"New display settings default to 500 Hz click snapping");
  check(TuneSnap.Apply(452300173,3,12500,[],0)==452300000&&TuneSnap.Apply(452300386,3,12500,[],0)==452300500,"500 Hz click snapping gives a fourth decimal digit of zero or five");check(TuneSnap.Apply(452300173,0,500,[],0)==452300173,"Fine click tuning remains available when snapping is off");
  view.SetMarkers([custom,custom with{Id=Guid.NewGuid(),Name="Other entry"}]);check(view.Overlaps(custom.FrequencyHz).Length==2&&view.Overlaps(custom.FrequencyHz).Select(c=>c.Id).Distinct().Count()==2,"Overlap inspection exposes distinct saved IDs at the same frequency");
  view.UpdateLayout();new System.Windows.Media.Imaging.RenderTargetBitmap(1000,600,96,96,System.Windows.Media.PixelFormats.Pbgra32).Render(view);var hit=view.MarkerLabelBounds.Single();var labelPoint=new Point(hit.Right-2,hit.Top+5);Guid[] inspected=[];view.OverlapsRequested+=ids=>inspected=ids;view.ClickAt(labelPoint,true);check(inspected.Length==2&&inspected.Contains(custom.Id),"Ctrl-click on the (+N) label text selects its overlapping saved IDs, not a frequency beneath the text");
  var research=new LcnResearch();string scope="DMR:DMR Tier III:Network 5:Site 1";research.Start(scope,461000000,[461200000,461225000]);var grant=DmrFollowingTests.TierGrant with{Network=5,Site=1};var voice=new DmrObservation(6,1,2,grant.Source,grant.Destination,true,true,"","Synthetic valid LC");
  void Control(DateTimeOffset time)=>research.Observe(new(grant,new("control","Synthetic control",false,461000000),time));void Voice(DateTimeOffset time,long frequency=461200000,DmrObservation? value=null)=>research.Observe(new(value??voice,new("voice","Synthetic voice",false,frequency),time));
  Control(now);Voice(now.AddMilliseconds(100));check(research.Snapshot() is [{Lcn:0x123,Hz:461200000,Matches:1}],"Tier III grant and matching timed full LC yield an unconfirmed carrier candidate");Voice(now.AddMilliseconds(200));check(research.Snapshot()[0].Matches==1,"Repeated voice packets do not inflate rapid correlation counts");
  Control(now.AddSeconds(6));Voice(now.AddSeconds(6.1));check(research.Snapshot()[0].Matches==2,"Later qualifying observations add research evidence without claiming confirmation");
  Voice(now.AddSeconds(6.2),461225000,voice with{Slot=1});Voice(now.AddSeconds(6.2),461225000,voice with{LinkValid=false});Voice(now.AddSeconds(6.2),461225000,voice with{Destination=999});check(research.Snapshot().Length==1,"Wrong-slot, failed-validation and wrong-TG voice cannot map a carrier");
  Voice(now.AddSeconds(6.3),461225000);check(research.Snapshot().All(c=>c.Status.StartsWith("Conflicting")),"Competing frequency associations remain explicit research conflicts");research.Stop();int total=research.Snapshot().Sum(c=>c.Matches);Control(now.AddSeconds(12));Voice(now.AddSeconds(12.1));check(research.Snapshot().Sum(c=>c.Matches)==total,"Stopped channel research retains evidence without collecting more");
 }
}
